/* Original synthesized game score. No recordings, downloads or third-party tracks. */
(function(root){
const SCORE={root:38,chords:[[0,3,7],[0,5,8],[-2,2,5],[-5,0,3]],melody:[7,10,12,10,7,5,3,5,7,12,15,12,10,7,5,3]};
function tempoForTravel(travel){const points=[[5.8,150],[8,136],[12,116],[22,90],[36,72]];if(travel<=points[0][0])return 150;for(let i=1;i<points.length;i++)if(travel<=points[i][0]){const[a,x]=points[i-1],[b,y]=points[i];return x+(y-x)*(travel-a)/(b-a)}return 72;}
const FX_PATTERNS={spawn:[62,69],chip:[55,62],hit:[72,79,84],combo:[76,79,83,88],escape:[45,40,33],wave:[48,55,60,67],win:[60,64,67,72,76,79],end:[55,51,48,43]};
const hz=midi=>440*Math.pow(2,(midi-69)/12);
class GameAudio{
constructor(){this.ctx=null;this.musicOn=true;this.effectsOn=true;this.volume=.6;this.duck=false;this.wave=1;this.tick=0;this.playing=false;this.nodes=new Set();this.travel=12;this.bpm=tempoForTravel(12);this.lastHit=0;}
prepare(){try{const Context=root.AudioContext||root.webkitAudioContext;if(!Context)return false;if(!this.ctx){this.ctx=new Context();this.master=this.ctx.createDynamicsCompressor();this.master.threshold.value=-20;this.master.ratio.value=5;this.master.connect(this.ctx.destination);this.musicBus=this.ctx.createGain();this.fxBus=this.ctx.createGain();this.musicBus.connect(this.master);this.fxBus.connect(this.master);this.fxBus.gain.value=.4;const buffer=this.ctx.createBuffer(1,this.ctx.sampleRate,this.ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;this.noiseBuffer=buffer;}this.ctx.resume().catch(()=>{});this.applyMix();return true}catch{return false}}
applyMix(){if(!this.ctx)return;const t=this.ctx.currentTime;this.musicBus.gain.setTargetAtTime(this.musicOn?this.volume*(this.duck?.015:.28):0,t,.2);this.fxBus.gain.setTargetAtTime(this.effectsOn?(this.duck?.035:.38):0,t,.08);}
configure({music=true,sound=true,voice=false,speed='steady',travel}={}){this.musicOn=music;this.effectsOn=sound;this.duck=voice;this.setPace(Number.isFinite(travel)?travel:(root.InkEngine?.paceFor(speed,voice?'voice':'type').travel||12));this.applyMix();}
setPace(travel){if(Number.isFinite(travel)&&travel>0){this.travel=travel;this.bpm=tempoForTravel(travel);}}
setMusic(on){this.musicOn=on;this.applyMix()}setEffects(on){this.effectsOn=on;this.applyMix()}setVolume(v){this.volume=Math.max(0,Math.min(1,v));this.applyMix()}setWave(wave){if(wave>this.wave){this.wave=wave;this.effect('wave')}else this.wave=wave;}
watch(node,stop){this.nodes.add(node);node.onended=()=>this.nodes.delete(node);if(stop!==undefined)node.stop(stop);}
note(midi,time,duration,gain=.14,type='triangle',bus=this.musicBus,cutoff=1500){const c=this.ctx;if(!c)return;const o=c.createOscillator(),filter=c.createBiquadFilter(),g=c.createGain();o.type=type;o.frequency.value=hz(midi);filter.type='lowpass';filter.frequency.value=cutoff;g.gain.setValueAtTime(.0001,time);g.gain.exponentialRampToValueAtTime(Math.max(.0002,gain),time+.014);g.gain.exponentialRampToValueAtTime(.0001,time+duration);o.connect(filter);filter.connect(g);g.connect(bus);o.start(time);this.watch(o,time+duration+.05);}
pad(notes,time,duration){for(const midi of notes)for(const cents of[-6,6]){const c=this.ctx,o=c.createOscillator(),f=c.createBiquadFilter(),g=c.createGain();o.type='sawtooth';o.frequency.value=hz(midi);o.detune.value=cents;f.type='lowpass';f.frequency.setValueAtTime(450,time);f.frequency.linearRampToValueAtTime(1100,time+duration*.65);g.gain.setValueAtTime(.0001,time);g.gain.linearRampToValueAtTime(.04,time+.3);g.gain.setValueAtTime(.04,time+duration*.7);g.gain.exponentialRampToValueAtTime(.0001,time+duration);o.connect(f);f.connect(g);g.connect(this.musicBus);o.start(time);this.watch(o,time+duration+.1);}}
noise(time,duration,level=.12,cutoff=1800,bus=this.musicBus){const c=this.ctx,s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=this.noiseBuffer;f.type='highpass';f.frequency.value=cutoff;g.gain.setValueAtTime(level,time);g.gain.exponentialRampToValueAtTime(.0001,time+duration);s.connect(f);f.connect(g);g.connect(bus);s.start(time);this.watch(s,time+duration+.02);}
drum(time,heavy=false){const c=this.ctx,o=c.createOscillator(),g=c.createGain();o.frequency.setValueAtTime(heavy?105:150,time);o.frequency.exponentialRampToValueAtTime(heavy?38:55,time+.22);g.gain.setValueAtTime(heavy?.65:.32,time);g.gain.exponentialRampToValueAtTime(.0001,time+.34);o.connect(g);g.connect(this.musicBus);o.start(time);this.watch(o,time+.36);}
schedule(){if(!this.playing||!this.ctx)return;const preset=SCORE;const beat=60/this.bpm;while(this.nextNote<this.ctx.currentTime+.25){const step=this.tick%16,bar=Math.floor(this.tick/16),chord=preset.chords[bar%preset.chords.length],rootNote=preset.root;const t=this.nextNote;if(this.musicOn){if(step===0){this.pad(chord.map(n=>rootNote+12+n),t,beat*4.1);this.drum(t,true);}if(step===8)this.drum(t,true);if(step%4===2)this.drum(t,false);if(step%2===0){this.note(rootNote+chord[(step/2)%chord.length],t,beat*.47,.17,'triangle',this.musicBus,850);this.noise(t,.045,.045,5500);}if(step%4===0||this.wave>=3&&step%2===1)this.note(rootNote+12+preset.melody[(step+bar*3)%16],t,beat*.8,.075,'triangle',this.musicBus,2100);if(step===12)this.noise(t,.14,.11,1800);}this.tick++;this.nextNote+=beat/4;}}
start(config){if(!this.prepare())return;this.pause();this.configure(config);this.wave=1;this.tick=0;this.playing=true;this.nextNote=this.ctx.currentTime+.03;this.schedule();this.interval=setInterval(()=>this.schedule(),90);}
pause(){this.playing=false;clearInterval(this.interval);for(const node of this.nodes){try{node.stop()}catch{}}this.nodes.clear();}
resume(){if(!this.prepare()||this.playing)return;this.playing=true;this.nextNote=this.ctx.currentTime+.04;this.schedule();this.interval=setInterval(()=>this.schedule(),90);}
stop(){this.pause();}
effect(kind='hit',combo=0){if(!this.effectsOn||!this.prepare())return;const c=this.ctx;let pattern=FX_PATTERNS[kind]||FX_PATTERNS.hit;const transpose=kind==='hit'?(this.lastHit++%3)*2:kind==='combo'?Math.min(7,Math.floor(combo/3)):0;const now=c.currentTime;pattern.forEach((n,i)=>this.note(n+transpose,now+i*(kind==='win'?.12:.055),kind==='end'?.4:.17,.14,kind==='escape'?'sawtooth':'triangle',this.fxBus,kind==='escape'?650:2900));if(kind==='hit')this.noise(now,.055,.13,3500,this.fxBus);if(kind==='combo')this.noise(now,.25,.1,5000,this.fxBus);if(kind==='wave')this.noise(now,.4,.2,2400,this.fxBus);}
}
root.InkAudio={GameAudio,SCORE,tempoForTravel,FX_PATTERNS};if(typeof module!=='undefined')module.exports={GameAudio,SCORE,tempoForTravel,FX_PATTERNS};
})(typeof window!=='undefined'?window:globalThis);
